mapper.update:
update outbox_event set status='PUBLISHED',published_at=current_timestamp(3),
    lease_token=null,lease_until=null,last_error=null,updated_at=current_timestamp(3)
where id=#{id} and status='PROCESSING' and lease_token=#{token}

update outbox_event set status=case when attempt_count >= 8 then 'FAILED' else 'PENDING' end,
    next_attempt_at=#{next},last_error=#{error},lease_token=null,lease_until=null,updated_at=current_timestamp(3)
where id=#{id} and lease_token=#{token}
